import{loadData,saveData}from"./storage.min.js";const tugasAwal=[{id:1,nama:"Belajar JavaScript",selesai:false},{id:2,nama:"Olahraga",selesai:false}];export function buatStoreTugas(){let daftar=loadData("daftarTugas",tugasAwal);function simpan(){saveData("daftarTugas",daftar)}return{semua:()=>[...daftar],tambah(nama){daftar.push({id:Date.now(),nama,selesai:false});simpan()},hapus(id){daftar=daftar.filter((tugas)=>tugas.id!==id);simpan()},edit(id,nama){daftar=daftar.map((tugas)=>tugas.id===id?{...tugas,nama}:tugas);simpan()},toggleSelesai(id){daftar=daftar.map((tugas)=>tugas.id===id?{...tugas,selesai:!tugas.selesai}:tugas);simpan()},filter(filter){if(filter==="selesai")return daftar.filter((tugas)=>tugas.selesai);if(filter==="belum")return daftar.filter((tugas)=>!tugas.selesai);return[...daftar]}}}
